changeSet.sql:
ALTER TABLE courier_location_inputs ADD COLUMN input_time_nanos INTEGER;

UPDATE courier_location_inputs
SET input_time_nanos = (EXTRACT(MICROSECONDS FROM input_time)::BIGINT % 1000000) * 1000;

ALTER TABLE courier_location_inputs
    ALTER COLUMN input_time_nanos SET NOT NULL,
    ADD CONSTRAINT uq_courier_location_input
        UNIQUE (courier_id, input_time, input_time_nanos, latitude, longitude);

ALTER TABLE courier_location_inputs DROP CONSTRAINT uq_courier_location_input;
-- Recover the original second if timestamp rounding carried into the next one, -- then truncate the preserved fraction to milliseconds before changing precision. ALTER TABLE courier_location_inputs ALTER COLUMN input_time TYPE TIMESTAMP(3) WITH TIME ZONE USING ( date_trunc('second', input_time) - CASE WHEN input_time_nanos >= 999999500 AND input_time = date_trunc('second', input_time) THEN INTERVAL '1 second' ELSE INTERVAL '0 seconds' END + (input_time_nanos / 1000000) * INTERVAL '1 millisecond' ), DROP COLUMN input_time_nanos;
ALTER TABLE courier_location_inputs ADD CONSTRAINT uq_courier_location_input UNIQUE (courier_id, input_time, latitude, longitude);
